package com.example.appointment.offering;
import com.example.appointment.common.BaseEntity; import javax.persistence.*;
@Entity @Table(name="service_offering") public class ServiceOffering extends BaseEntity { @Column(nullable=false,unique=true) private String name; @Column(nullable=false) private int durationMinutes; private String description; @Column(nullable=false) private boolean active=true; protected ServiceOffering(){} public ServiceOffering(String n,int d,String x){name=n;durationMinutes=d;description=x;} public String getName(){return name;} public int getDurationMinutes(){return durationMinutes;} public String getDescription(){return description;} public boolean isActive(){return active;} public void update(String n,int d,String x){name=n;durationMinutes=d;description=x;} public void setActive(boolean a){active=a;} }
